@ac_proof(proof_id='test_models_have_no_service_deps', ac_ids=['AC-ledger.34.3'], ci_tier='pr_ci')
def test_AC12_34_3_model_layer_never_imports_a_service():
    'AC-ledger.34.3'; model_dirs = [SRC / 'models', *sorted(SRC.glob('*/orm'))]; offenders = []
    for path in sorted((p for d in model_dirs for p in d.rglob('*.py'))):
        for node in ast.walk(ast.parse(path.read_text())):
            mods = []
            if isinstance(node, ast.ImportFrom) and node.module: mods = [node.module]
            elif isinstance(node, ast.Import): mods = [a.name for a in node.names]
            offenders.append(path.name) if any((m.startswith('src.services') for m in mods)) else None
    assert not offenders, f'model layer imports services (upward edge): {sorted(set(offenders))}'
